function e(e,t,n={}){let r=n.zThreshold??2.5,i=n.minSample??5,a=e.filter(e=>e.type===`expense`),o=new Map;for(let e of a){let t=e.category_id??`__uncategorized__`;o.has(t)||o.set(t,[]),o.get(t).push(e)}let s=[];for(let[e,n]of o){if(n.length<i)continue;let a=n.map(e=>Number(e.amount)),o=a.reduce((e,t)=>e+t,0)/a.length,c=a.reduce((e,t)=>e+(t-o)**2,0)/a.length,l=Math.sqrt(c);if(l!==0)for(let i of n){let n=(Number(i.amount)-o)/l;n>=r&&s.push({transaction:i,zScore:n,categoryLabel:e===`__uncategorized__`?`Uncategorized`:t.get(e)??`a category`})}}return s.sort((e,t)=>t.zScore-e.zScore)}function t(e,t=3){let n=new Map;for(let t of e){if(t.type!==`expense`)continue;let e=t.transaction_date.slice(0,7);n.set(e,(n.get(e)??0)+Number(t.amount))}let r=Array.from(n.keys()).sort().map(e=>({month:e,total:n.get(e)}));if(r.length<2)return{history:r,projectedNextMonth:r[0]?.total??0,trendPct:0,hasEnoughData:!1};let i=r.slice(-t),a=i.reduce((e,t)=>e+t.total,0)/i.length,o=r[r.length-1]?.total??0;return{history:r,projectedNextMonth:a,trendPct:o>0?(a-o)/o*100:0,hasEnoughData:!0}}export{t as n,e as t};